def patch_main_js():
    file_path = "main.js"
    if not os.path.exists(file_path):
        print(f"Error: {file_path} not found")
        return

    with open(file_path, "r", encoding="utf-8") as f:
        content = f.read()

    # Normalize line endings
    content = content.replace("\r\n", "\n")

    # Show comanda in cashier table
    target_main = '<td style="${isPaid ? \'text-decoration: line-through;\' : \'\'}">${order.productEmoji || \'\'} ${order.productName || \'Produto\'} ${isPaid ? \'<strong style="color: #3ab55b; margin-left: 8px;">(PAGO)</strong>\' : \'\'}</td>'
    replacement_main = '<td style="${isPaid ? \'text-decoration: line-through;\' : \'\'}">${order.productEmoji || \'\'} ${order.productName || \'Produto\'}${order.mesa_comanda ? ` <span style="color:#fc4b15; font-size:12px; margin-left:8px; font-weight:600;">(${order.mesa_comanda})</span>` : \'\'} ${isPaid ? \'<strong style="color: #3ab55b; margin-left: 8px;">(PAGO)</strong>\' : \'\'}</td>'
    content = content.replace(target_main, replacement_main)

    # Restore windows line endings
    content = content.replace("\n", "\r\n")

    with open(file_path, "w", encoding="utf-8") as f:
        f.write(content)
    print("main.js patched successfully")


if __name__ == "__main__":
    patch_garcom_html()
    patch_garcom_js()
    patch_fila_js()
    patch_main_js()
